-- mod-guild-adventure: walking links the travel node graph of mod-playerbots lacks (GA_world). GENERATED by
-- tools/gen_road_links.py from the server's navmesh (tools/navpath); run the script again, do not edit.
-- Applied by the worldserver's DB updater (re-applied when the file changes); idempotent. RoadMap::Load
-- reads it at startup (".ga reload" too) as two walking links each. Docs: docs/orders.md
-- "Road links from the navmesh".
-- points: "x y z" a few yards apart, from `from_node` to `to_node` (playerbots_travelnode ids).
CREATE TABLE IF NOT EXISTS `ga_road_link` (
    `id`        INT UNSIGNED      NOT NULL,
    `map_id`    SMALLINT UNSIGNED NOT NULL,
    `from_node` INT UNSIGNED      NOT NULL COMMENT 'playerbots_travelnode.id',
    `to_node`   INT UNSIGNED      NOT NULL COMMENT 'playerbots_travelnode.id',
    `distance`  FLOAT             NOT NULL COMMENT 'yards walked',
    `points`    MEDIUMTEXT        NOT NULL,
    `comment`   VARCHAR(255)      NOT NULL DEFAULT '',
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Guild Adventure: road links from the navmesh';

DELETE FROM `ga_road_link`;

-- Links of the travel node graph RoadMap::Load leaves out: their walked path jumps up or down where the
-- navmesh has no walk of reasonable length (the walk between their nodes, when there is one, is above).
CREATE TABLE IF NOT EXISTS `ga_road_unlink` (
    `from_node` INT UNSIGNED      NOT NULL COMMENT 'playerbots_travelnode.id',
    `to_node`   INT UNSIGNED      NOT NULL COMMENT 'playerbots_travelnode.id',
    `comment`   VARCHAR(255)      NOT NULL DEFAULT '',
    PRIMARY KEY (`from_node`, `to_node`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Guild Adventure: travel node links left out';

DELETE FROM `ga_road_unlink`;
